#!/usr/bin/env bash
# One GitHub Pages site for the repo. The door (the Value app) is the site root: /Micar-com/
# /Micar-com/value/  forwards to the root, hash intact, so every printed QR code and the old-repo redirect still land on the car
# /Micar-com/tuner/  a redirect to the world (the Tuner is absorbed into the Garage; apps/tuner is no longer shipped)
# /Micar-com/strip/  a redirect to the Strip on the sim server (race as a guest, no account)
# /Micar-com/garage/ the Garage's old address: a small page that forwards to #/garage, generated by tools/build-garage.ts (carries the footer)
# /Micar-com/cars/   plain-HTML model pages, plus sitemap.xml, robots.txt and llms.txt at the site's root (/Micar-com/), so crawlers
#                    and AI readers see real text. Crawlers read robots.txt only at the host's root, which a project site does not
#                    own, so its Sitemap line waits for a domain of our own; every page links the sitemap from its <head> meanwhile
set -euo pipefail
cd "$(dirname "$0")/.."
rm -rf site && mkdir -p site/value site/tuner site/strip site/garage
BASE_PATH=/Micar-com/ pnpm --filter @micar/value build
cp -r apps/value/dist/. site/
cp tools/value-alias.html site/value/index.html
# the tuner now lives in the world's Garage; the old link forwards there (no hash carried over)
cp tools/tuner-redirect.html site/tuner/index.html
cp tools/strip-redirect.html site/strip/index.html
pnpm --filter @micar/value exec tsx ../../tools/build-garage.ts
grep -q '<footer class="mc-foot"' site/garage/index.html
touch site/.nojekyll
# the plain-HTML layer for search engines and AI readers: /cars/ pages, sitemap.xml, robots.txt, llms.txt (tools/build-seo.ts)
pnpm --filter @micar/value exec tsx ../../tools/build-seo.ts
grep -q '<h1>' site/cars/index.html && grep -q 'Sitemap:' site/robots.txt
